CREATE TABLE users (id INTEGER PRIMARY KEY AUTOINCREMENT, username VARCHAR(50) NOT NULL, password VARCHAR(255) NOT NULL, email VARCHAR(100) NOT NULL, two_factor_code VARCHAR(20), created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE practice_areas (id INTEGER PRIMARY KEY AUTOINCREMENT, title VARCHAR(100) NOT NULL, description TEXT, icon VARCHAR(50) DEFAULT 'fas fa-balance-scale', created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE attorneys (id INTEGER PRIMARY KEY AUTOINCREMENT, name VARCHAR(100) NOT NULL, position VARCHAR(100), bio TEXT, image VARCHAR(255), email VARCHAR(100), phone VARCHAR(50), created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE messages (id INTEGER PRIMARY KEY AUTOINCREMENT, name VARCHAR(100) NOT NULL, email VARCHAR(100) NOT NULL, phone VARCHAR(50), subject VARCHAR(200), message TEXT NOT NULL, is_read INTEGER DEFAULT 0, created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE posts (id INTEGER PRIMARY KEY AUTOINCREMENT, title VARCHAR(255) NOT NULL, content TEXT NOT NULL, image VARCHAR(255), created_at DATETIME DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE settings (setting_key VARCHAR(50) PRIMARY KEY, setting_value TEXT);
CREATE TABLE case_results (id INTEGER PRIMARY KEY AUTOINCREMENT, title VARCHAR(255) NOT NULL, amount VARCHAR(50), case_type VARCHAR(100), description TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE clients (id INTEGER PRIMARY KEY AUTOINCREMENT, name VARCHAR(100) NOT NULL, email VARCHAR(100) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE newsletter_subscribers (id INTEGER PRIMARY KEY AUTOINCREMENT, email VARCHAR(100) NOT NULL UNIQUE, subscribed_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE page_views (view_date DATE, page_url VARCHAR(255), views INTEGER DEFAULT 0, PRIMARY KEY (view_date, page_url));
CREATE TABLE custom_forms (id INTEGER PRIMARY KEY AUTOINCREMENT, title VARCHAR(255) NOT NULL, fields_json TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE audit_logs (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, action VARCHAR(255), ip_address VARCHAR(45), created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE appointments (id INTEGER PRIMARY KEY AUTOINCREMENT, name VARCHAR(100), email VARCHAR(100), phone VARCHAR(50), appointment_date DATE, appointment_time TIME, meeting_link VARCHAR(255), status VARCHAR(50) DEFAULT 'pending', created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE invoices (id INTEGER PRIMARY KEY AUTOINCREMENT, client_id INTEGER, amount DECIMAL(10,2), description TEXT, status VARCHAR(50) DEFAULT 'unpaid', payment_gateway_used VARCHAR(50) NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP);